import React, { useEffect } from 'react';
import { CDetailPage, Button, Alert } from '@cloud-materials/common';
import { MemoryRouter as Router, Switch, Route } from 'react-router-dom';
import { observer } from '@formily/react';
import type { StatusType } from '@cloud-materials/common/es/CStatus/interface';

import { mockData } from './shared/mockData';
import { BasicDetailInfoSectionList } from '../arco';
import CCopy from '../../CCopy';
import CInlineEdit from '../../CInlineEdit';
import type { TableConfig } from '../../CTable';
import CTable from '../../CTable';
import { useDetailPage } from '../react';

const { defineConfig } = CDetailPage;
const DetailPage = () => {
  const config = defineConfig<InstanceBasicInfo>({
    renderActiveTabContent({ content, tabKey, detailPage }) {
      if (tabKey === 'params_setting') {
        if (Math.random() > 0.5) {
          return (
            <Alert
              content={
                <div>
                  current instance is not running, please retry later&emsp;
                  <Button
                    onClick={() => {
                      detailPage?.refresh();
                    }}
                  >
                    retry
                  </Button>
                </div>
              }
            />
          );
        }
      }

      if (tabKey === 'connectity') {
        return (
          <Alert
            content={
              <div>
                current instance is not running, can not view connectity info please retry later&emsp;
                <Button
                  onClick={() => {
                    detailPage?.refresh();
                  }}
                >
                  retry
                </Button>
              </div>
            }
          />
        );
      }

      return <div>{content}</div>;
    },
    cDetailPageHeaderProps: ({ data, detailPage }) => {
      return {
        title: data?.InstanceName,
        navProps: {
          routes: [
            {
              title: '实例列表',
              path: '/',
              onClick: () => {},
            },
            {
              title: '实例详情',
              path: '/1',
              onClick: () => {},
            },
          ],
        },
        statusProps: {
          // 此处需要将接口返回的status结构转换成组件需要的类型，
          // 此处仅作示例
          status: 'running' as StatusType,
          text: '运行中',
        },
        onBack: () => {
          detailPage.setData({ ...data, InstanceId: '这里测试setData' });
        },
        operationMenuProps: {
          operations: [
            {
              name: '切换Tab',
              onClick: () => {
                detailPage?.setActiveTabKey('params_setting');
              },
              arcoButtonProps: {
                type: 'primary',
              },
            },
          ],
        },
      };
    },
    // cDetailPageContentProps: {

    // },
    tabs: [
      {
        key: 'instance_info',
        title: '实例信息',
        render: () => {
          return <BasicDetailInfo />;
        },
        noticeComponent: 'Alert',
        noticeComponentProps: () => {
          return {
            content: '这是一条详情页的提示内容',
          };
        },
      },
      {
        key: 'params_setting',
        title: '参数配置',
        visible: ({ data }) => {
          return data?.Status === 'running';
        },
        render: () => {
          return <ParamsSetting />;
        },
      },
      {
        key: 'connectity',
        title: '连接管理',
        visible: ({ data }) => {
          return data?.Status === 'running';
        },
        render: () => {
          return <h1>连接管理</h1>;
        },
      },
    ],
    /** 获取详情页数据 */
    fetcher: async () => {
      const req = new Promise(resolve => {
        setTimeout(() => {
          resolve(mockData);
        }, 1000);
      });
      const res = await req;

      return {
        data: res || {},
      };
    },
  });
  return <CDetailPage config={config} />;
};

export default () => {
  return (
    <Router initialEntries={['/1']} initialIndex={0}>
      <Switch>
        <Route path="/1" component={() => <DetailPage />} />
      </Switch>
    </Router>
  );
};

