const { defineConfig: defineDetailInfoConfig } = BasicDetailInfoSectionList;
interface Props {
  history?: any;
}

export const BasicDetailInfo: React.FC<Props> = observer(() => {
  const infoSectionListConfig = defineDetailInfoConfig<any, InstanceBasicInfo>({
    listData: [
      {
        title: '实例信息',
        infoItemList: [
          {
            label: '实例ID',
            // 默认过长省略
            // enableEllipsis: true,
            content: ({ data }) => {
              return data?.InstanceId;
            },
            extraContent: ({ data }) => {
              return <CCopy text={data?.InstanceId} />;
            },
          },
          {
            label: '实例名称',
            content: ({ data, detailPage }) => {
              return (
                <CInlineEdit
                  rules={[
                    {
                      required: true,
                      message: '请输入实例名称',
                    },
                    {
                      message: '长度需要在2-128个字符内',
                      minLength: 2,
                      maxLength: 128,
                    },
                  ]}
                  onSubmit={async value => {
                    const req = new Promise(resolve => {
                      setTimeout(() => {
                        resolve(value);
                      }, 1000);
                    });
                    await req;
                    detailPage.setData({
                      ...data,
                      InstanceName: value,
                    });
                    detailPage.setData({
                      ...detailPage.data,
                      InstanceName: value,
                    });
                  }}
                  value={data?.InstanceName}
                />
              );
            },
          },
        ],
      },
      {
        title: '配置信息',
        infoItemList: [
          {
            label: '数据库版本',
            content: ({ data }) => {
              return data?.BigVersion;
            },
          },
          {
            label: '规格',
            content: ({ data }) => {
              return data?.RSCount;
            },
          },
          {
            label: '网络类型',
            content: ({ data }) => {
              return data?.NetworkType;
            },
          },
        ],
      },
    ],
  });

  useEffect(() => {
    return () => {
      console.log('[CDetailpage]basic demo unmounted');
    };
  }, []);

  return <BasicDetailInfoSectionList config={infoSectionListConfig} />;
});

