// 参数配置
interface ParamsData {
  ParamsName: string;
  ParamsValue: string;
  NeedRestart: boolean;
}

interface ParamsSettingProps {}
const ParamsSetting: React.FC<ParamsSettingProps> = observer(() => {
  // 获取detailPage对象
  const detailPage = useDetailPage();
  const tableConfig: TableConfig<ParamsData> = {
    rowKey: record => record?.ParamsName,
    columns: [
      {
        title: '参数名称',
        dataIndex: 'ParamsName',
        component: ({ rowData }) => {
          return <>{rowData?.ParamsName}</>;
        },
      },
      {
        title: '参数值',
        dataIndex: 'ParamsValue',
        component: ({ rowData }) => {
          return <>{rowData?.ParamsValue}</>;
        },
      },
      {
        title: '是否需要重启',
        dataIndex: 'NeedRestart',
        component: ({ rowData }) => {
          return <>{rowData?.NeedRestart ? '是' : '否'}</>;
        },
      },
    ],
    fetcher: async () => {
      const data: ParamsData[] = [
        {
          ParamsName: '参数1',
          ParamsValue: '参数1',
          NeedRestart: false,
        },
        {
          ParamsName: '参数2',
          ParamsValue: '参数2',
          NeedRestart: true,
        },
      ];
      const req = new Promise(resolve => {
        setTimeout(() => {
          resolve(data);
          return;
        }, 1000);
      });
      const res = await req;
      return {
        data: res as ParamsData[],
        total: (res as ParamsData[])?.length,
      };
    },
  };
  return (
    <>
      <Button
        style={{
          width: 150,
        }}
        type={'primary'}
        onClick={() => {
          detailPage.changeActiveTab('instance_info');
        }}
      >
        跳转到实例详情Tab
      </Button>
      <CTable config={tableConfig} />
    </>
  );
});

